import{_ as i,o as n,c as u,a2 as o}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Kanuni ya Teknolojia ya Kioo cha Nakala","description":"","frontmatter":{},"headers":[],"relativePath":"sw/63-复制镜技术原理.md","filePath":"sw/63-复制镜技术原理.md","lastUpdated":1789183869000}'),k={name:"sw/63-复制镜技术原理.md"};function t(e,a,l,h,w,s){return n(),u("div",null,[...a[0]||(a[0]=[o('<h1 id="kanuni-ya-teknolojia-ya-kioo-cha-nakala" tabindex="-1">Kanuni ya Teknolojia ya Kioo cha Nakala <a class="header-anchor" href="#kanuni-ya-teknolojia-ya-kioo-cha-nakala" aria-label="Permalink to &quot;Kanuni ya Teknolojia ya Kioo cha Nakala&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>63</td></tr><tr><td>Moduli</td><td>Mfumo wa Teknolojia na Nishati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Kioo cha nakala, nakala ya kioo, mpango wa uchunguzi wa kale, uchafuzi wa chini, sheria ya nafasi</td></tr></tbody></table><h2 id="_1-njia-ya-asili-na-asili-ya-teknolojia-ya-kioo-cha-nakala" tabindex="-1">1. Njia ya Asili na Asili ya Teknolojia ya Kioo cha Nakala <a class="header-anchor" href="#_1-njia-ya-asili-na-asili-ya-teknolojia-ya-kioo-cha-nakala" aria-label="Permalink to &quot;1. Njia ya Asili na Asili ya Teknolojia ya Kioo cha Nakala&quot;">​</a></h2><p>Teknolojia ya kioo cha nakala ni moja ya teknolojia mbili za msingi za mpango wa uchunguzi wa kale wa ustaarabu wa ushirika wa nanga (nyingine ni teknolojia ya ujenzi wa nafasi ya kutengwa), kazi yake ya msingi ni kufanya nakala ya kioo ya usawa wa juu ya kiwango cha lengo au eneo la lengo, ili kazi ya uchunguzi wa kale na utafiti iweze kufanyika ndani ya nakala, na kwa hivyo kuepuka kuingilia na kuchafua kiwango cha asili.</p><p>Asili ya teknolojia ya kioo cha nakala inaweza kutafutwa hadi katika utafiti wa ufalme wa &quot;kubadilisha nafasi&quot; wa mfumo wa mipango ya sheria za nafasi. Timu ya utafiti, wakati wa kuchunguza mifano ya ubadilishaji wa nafasi-vifaa, iligundua kuwa kupitia kupiga picha na kujenga upya kamili za sheria za muundo wa nafasi wa eneo la lengo, inawezekana kutoa katika nafasi nyingine nakala ya kioo inayolingana sana na eneo la asili. Ugunduzi huu, kwa njia ya mabadiliko mengi ya uboreshaji ya injini ya udedukaji ya tunda la kuzidisha, hatimaye uliunda mfumo wa kioo cha nakala unaoweza kutekelezwa kwa uhandisi.</p><h2 id="_2-kanuni-ya-kazi-ya-kioo-cha-nakala" tabindex="-1">2. Kanuni ya Kazi ya Kioo cha Nakala <a class="header-anchor" href="#_2-kanuni-ya-kazi-ya-kioo-cha-nakala" aria-label="Permalink to &quot;2. Kanuni ya Kazi ya Kioo cha Nakala&quot;">​</a></h2><p>Mchakato wa kazi wa kioo cha nakala umegawanywa katika hatua nne, kila hatua ina vigezo vya teknolojia vikali na mipaka ya usalama:</p><table tabindex="0"><thead><tr><th>Hatua</th><th>Jina</th><th>Maelezo ya Kazi</th><th>Vigezo vya Msingi</th></tr></thead><tbody><tr><td>Hatua ya kwanza</td><td>Kupiga picha sheria</td><td>Kupiga picha sheria za vipimo vyote vya eneo la lengo, kupata taarifa zote kama muundo wa nafasi, mgawanyiko wa vifaa, uwanja wa nishati, mabaki ya fahamu, n.k.</td><td>Usahihi wa kupiga picha si chini ya 0,001 dakika ya sheria, ufunuo wa kupiga picha ≥99,99%</td></tr><tr><td>Hatua ya pili</td><td>Usimbaji wa taarifa</td><td>Kusimamia taarifa nyingi sana zilizopatikana kupitia kupiga picha kuwa vifungu vya data za sheria vinavyoweza kusafirishwa, kuondoa ziada na kuthibitisha ukamilifu</td><td>Tathmini ya kukandamiza usimbaji ni takriban 10^6:1, uthibitisho hutumia algoritmu ya hash ya nanga</td></tr><tr><td>Hatua ya tatu</td><td>Ujenzi wa kioo upya</td><td>Kujenga upya nakala ya kioo ya eneo la lengo ndani ya nafasi ya kutengwa kulingana na kifungu cha data za sheria</td><td>Uaminifu wa ujenzi wa upya ≥99,95%, upotofu wa ujenzi wa upya lazima uwe ndani ya upeo unaodhibitiwa</td></tr><tr><td>Hatua ya nne</td><td>Usawazishaji wa usawazishaji</td><td>Kufanya usawazishaji wa kila mara kati ya nakala ya kioo na eneo la asili, kuhakikisha kwamba mabadiliko katika mchakato wa utafiti yanaweza kufuatilika</td><td>Kucheleweshwa kwa usawazishaji ≤0,1 sekunde, masafa ya usawazishaji yanaweza kurekebishwa kulingana na mahitaji ya utafiti</td></tr></tbody></table><p>&quot;Nakala&quot; ya kioo cha nakala sio kloni rahisi ya vifaa, bali ujenzi wa upya wa kiwango cha sheria kulingana na sheria za nafasi. Nakala ya kioo inalingana sana na eneo la asili katika muundo wa kimwili, mgawanyiko wa nishati, na hata kiwango cha mabaki ya fahamu, lakini kwa asili ni mfano wa nafasi wa kujitegemea, na mabadiliko yake ya ndani hayathiri eneo la asili kwa kinyume.</p><h2 id="_3-muundo-wa-uhandisi-wa-mfumo-wa-kioo-cha-nakala" tabindex="-1">3. Muundo wa Uhandisi wa Mfumo wa Kioo cha Nakala <a class="header-anchor" href="#_3-muundo-wa-uhandisi-wa-mfumo-wa-kioo-cha-nakala" aria-label="Permalink to &quot;3. Muundo wa Uhandisi wa Mfumo wa Kioo cha Nakala&quot;">​</a></h2><p>Mfumo wa kioo cha nakala kwa uhandisi unajumuisha mifumo mitatu ya ndogo:</p><ol><li><strong>Mfumo wa ndogo wa kupiga picha</strong>: Safu ya kupiga picha sheria iliyowekwa karibu na kiwango cha lengo, inayoendeshwa na moduli ya uelewa wa nafasi, inaweza kupiga picha malengo kwa viwango tofauti kutoka kiwango cha sayari hadi kiwango cha eneo. Safu ya kupiga picha inachukua muundo usioingilia, inapokea tu taarifa za sheria kwa utulivu, haitofanyi nishati yoyote kwenye eneo la lengo</li><li><strong>Mfumo wa ndogo wa usafirishaji</strong>: Njia ya usafirishaji wa data za sheria kulingana na teknolojia ya mawasiliano kati ya viwango, inasafirisha data za kupiga picha zilizosimamiwa hadi kituo cha utafiti ambapo nafasi ya kutengwa ipo. Mchakato wa usafirishaji unachukua usimbaji wa siri wa mwisho hadi mwisho, kuzuia data za sheria kubadilishwa au kuibiwa wakati wa usafirishaji</li><li><strong>Mfumo wa ndogo wa ujenzi wa upya</strong>: Safu ya ujenzi wa kioo upya iliyowekwa ndani ya nafasi ya kutengwa, inayoendeshwa na moduli ya ubadilishaji wa nafasi, inajenga upya eneo la lengo ndani ya nafasi ya kutengwa kulingana na kifungu cha data za sheria. Ukubwa wa safu ya ujenzi wa upya unamuamua kiwango cha juu cha eneo kinachoweza kunakaliwa</li></ol><p>Viwango vya usambazaji wa mfumo wa kioo cha nakala vimegawanywa katika viwango vitatu:</p><ul><li><strong>Kiwango cha sayari</strong>: Inaweza kunakali kioo cha sayari kamili, inatumika kwa utafiti wa uchunguzi wa kale wa kiwango cha ustaarabu</li><li><strong>Kiwango cha eneo</strong>: Inaweza kunakali maeneo ya kiwango cha bara au nchi, inatumika kwa utafiti wa maeneo muhimu</li><li><strong>Kiwango cha tovuti</strong>: Inaweza kunakali mabaki au mandhari mahususi, inatumika kwa kuchimba kwa undani wa uchunguzi wa kale</li></ul><h2 id="_4-vizuizi-vya-maadili-na-usalama-vya-teknolojia-ya-kioo-cha-nakala" tabindex="-1">4. Vizuizi vya Maadili na Usalama vya Teknolojia ya Kioo cha Nakala <a class="header-anchor" href="#_4-vizuizi-vya-maadili-na-usalama-vya-teknolojia-ya-kioo-cha-nakala" aria-label="Permalink to &quot;4. Vizuizi vya Maadili na Usalama vya Teknolojia ya Kioo cha Nakala&quot;">​</a></h2><p>Ingawa teknolojia ya kioo cha nakala ina nguvu, matumizi yake yamewekwa chini ya vizuizi vikali vya maadili na usalama:</p><ul><li><strong>Kanuni ya kurudisha maarifa tu</strong>: Matokeo ya utafiti wa uchunguzi wa kale unaofanywa ndani ya nakala ya kioo yanarudishwa kwa kiwango kuu tu kwa njia ya maarifa, haitwiwi kuleta vifaa, nishati, au viumbe hai yoyote kutoka kwa nakala ya kioo kurudi kwenye kiwango cha asili au kiwango cha kuu</li><li><strong>Kanuni ya kutokuingilia</strong>: Mchakato wa kupiga picha haupaswi kusababisha uingiliaji wowote katika utendaji wa kawaida wa eneo la lengo, safu ya kupiga picha lazima ibaki katika hali ya uangalizi wa utulivu</li><li><strong>Kanuni ya kuharibu kioo</strong>: Baada ya kumaliza utafiti, nakala ya kioo lazima iharibike kwa usalama kulingana na mchakato wa kiwango cha kawaida, haitwiwi kuhifadhiwa kwa muda mrefu au kubadilishwa kwa matumizi mengine</li><li><strong>Utunzaji wa mabaki ya fahamu</strong>: Ikiwa nakala ya kioo ina mabaki ya fahamu, lazima tathminiwa na kutunzwa kulingana na mchakato wa utunzaji wa aina tatu za maisha ya kushangaza, haitwiwi kuchukua mabaki ya fahamu kama data zisizo na uhai</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kanuni ya teknolojia ya kioo cha nakala ni uhalishaji wa teknolojia wa kanuni ya &quot;angalia kwanza, kisha uingiliane kwa kikomo&quot;. Inaruhusu watafiti wa Hengyuanzhou kufanya uchunguzi wa kale na utafiti wa kina kwenye lengo bila kugusa kiwango cha asili, na kutatua kwa msingi tatizo la uchafuzi na uingiliaji katika uchunguzi wa kale kati ya viwango. Mchanganyiko wa kioo cha nakala na nafasi ya kutengwa, unaunda msingi wa teknolojia wa mpango wa utafiti wa uchafuzi wa chini wa ustaarabu wa ushirika.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>64-Teknolojia ya Ujenzi wa Nafasi ya Kutengwa</li><li>85-Mpango wa Uchunguzi wa Kale wa Njia ya Nje wa Kioo cha Nakala</li><li>62-Utekelezaji wa Teknolojia ya Sheria ya Nafasi</li></ul>',21)])])}const m=i(k,[["render",t]]);export{d as __pageData,m as default};
